export function recordLeafBlueprint(
  e: { leafId: string; project: string; epicBaseSha?: string | null; specJson?: string | null },
  now: number = Date.now(),
): void {
  try {
    openDb().prepare(
      `INSERT INTO leaf_blueprint (leafId, project, epicBaseSha, specJson, originalSpecJson, specRev, recordedAt)
       VALUES (?,?,?,?,?,0,?)
       ON CONFLICT(leafId) DO UPDATE SET
         epicBaseSha=excluded.epicBaseSha, specJson=excluded.specJson, specRev=0, recordedAt=excluded.recordedAt`,
    ).run(e.leafId, e.project, e.epicBaseSha ?? null, e.specJson ?? null, e.specJson ?? null, now);
  } catch { /* best-effort */ }
}
```

